    def canCompleteCircuit(self, gas: List[int], cost: List[int]) -> int:
        n = len(gas)
        if sum(gas) - sum(cost) < 0:
            return -1

        curGas = 0
        start = 0
        for i in range(n):
            curGas += gas[i] - cost[i]
            if curGas < 0:
                start = i + 1
                curGas = 0
        return start

