class Solution:
    def max_possible_f(self, n: int, edges: List[List[int]], usage: List[int]) -> int:
        # Helper functions
        def find(par, u):
            """Find the root parent with path compression."""
            if par[u] != u:
                par[u] = find(par, par[u])
            return par[u]

        def unite(par, sz, use, u, v):
            """Union two sets."""
            u = find(par, u)
            v = find(par, v)
            if u != v:
                par[u] = v
                sz[v] += sz[u]
                use[v] += use[u]

        def is_valid(fp):
            """Check if `fp` is a valid solution with given frequency constraints."""
            par = [i for i in range(n + 1)]
            sz = [1] * (n + 1)
            use = [0] + usage[:]  # 1-based indexing
            for u, v, w in edges:
                if w < fp:
                    unite(par, sz, use, u, v)

            total_usage = sum(usage)

            for i in range(1, n + 1):
                root = find(par, i)
                if root == i:  # Only check root nodes
                    if total_usage - use[root] < sz[root]:
                        return False
            return True

        # Sort edges by weight
        edges.sort(key=lambda x: x[2])

        # Binary search to find the max possible f(p)
        lo, hi = 0, 10000
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if is_valid(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo
